/* @lc app=leetcode id=2532 lang=kotlin */
class Solution { fun findCrossingTime(n: Int, k: Int, time: Array<IntArray>): Int = java.util.PriorityQueue<IntArray> { a, b -> a[0] - b[0] }.let { l -> java.util.PriorityQueue<IntArray> { a, b -> a[0] - b[0] }.let { r -> java.util.PriorityQueue<IntArray> { a, b -> if (a[0] != b[0]) b[0] - a[0] else b[1] - a[1] }.let { ll -> java.util.PriorityQueue<IntArray> { a, b -> if (a[0] != b[0]) b[0] - a[0] else b[1] - a[1] }.let { rr -> IntArray(3).also { it[0] = n }.let { s -> (0 until k).forEach { ll.add(intArrayOf(time[it][0] + time[it][2], it)) }.run { while (s[0] > 0 || r.isNotEmpty() || rr.isNotEmpty()) (if (rr.isEmpty() && (r.isEmpty() || r.peek()[0] > s[1]) && (s[0] == 0 || ll.isEmpty() && (l.isEmpty() || l.peek()[0] > s[1]))) java.lang.Math.min(if (s[0] > 0 && l.isNotEmpty()) l.peek()[0] else Int.MAX_VALUE, if (r.isNotEmpty()) r.peek()[0] else Int.MAX_VALUE).also { s[1] = it } else 0).also { while (l.isNotEmpty() && l.peek()[0] <= s[1]) l.poll().also { ll.add(intArrayOf(time[it[1]][0] + time[it[1]][2], it[1])) } }.also { while (r.isNotEmpty() && r.peek()[0] <= s[1]) r.poll().also { rr.add(intArrayOf(time[it[1]][0] + time[it[1]][2], it[1])) } }.also { if (rr.isNotEmpty()) rr.poll().also { s[1] += time[it[1]][2] }.also { if (s[0] > 0) l.add(intArrayOf(s[1] + time[it[1]][3], it[1])) else s[2] = java.lang.Math.max(s[2], s[1]) } else if (ll.isNotEmpty()) ll.poll().also { s[1] += time[it[1]][0] }.also { r.add(intArrayOf(s[1] + time[it[1]][1], it[1])) }.also { s[0]-- } } }.run { s[2] } } } } } } }